Let $h>0$, $\varepsilon>0$, and let $\alpha \in \mathrm{DC}_d$. Denote by $\mathcal{R}_c$ the set of energies $E$ for which the $2m$-dimensional center cocycle $(\alpha, C_\varepsilon^\infty(E, \cdot))$ is $C_h^\omega$-reducible, that is, there exists $B \in C_h^\omega(\mathbb{T}^d, \mathrm{GL}(2m, \mathbb{C}))$ such that
\begin{equation*}
B(\theta+\alpha)^{-1} C_\varepsilon^\infty(E, \theta) B(\theta) = \Lambda := 
{\mathrm{diag}}\bigl(e^{2\pi i\rho_1},\dots,e^{2\pi i\rho_{2m}}\bigr).
\end{equation*}
Assume $E \in \mathcal{R}_c$ and $x \in \mathbb{T}$. If $E$ is an eigenvalue of the operator $\mathbf{H}_{\varepsilon W,V,\alpha,x}$ with an eigenfunction $u \in \ell^1(\mathbb{Z}^d)$, then the following hold:
\begin{enumerate}
    \item there exist an index $1 \le j \le 2m$ and $k \in \mathbb{Z}^d$ such that 
    $\rho_j - x = \langle k, \alpha \rangle \mod \mathbb{Z},$
    and in particular, $\Im \rho_j = 0$;
    \item the corresponding eigenfunction $u \in \ell^1(\mathbb{Z}^d)$ decays exponentially: $|u_n|\le C  e^{-2\pi h|n|}.$

\end{enumerate}
